def insert(intervals, newInterval):
    ns, ne = newInterval
    left, right = [], []
    for it in intervals:
        if it[1] < ns:
            left.append(it)
        elif it[0] > ne:
            right.append(it)
        else:
            ns = min(ns, it[0])
            ne = max(ne, it[1])
    return left + [[ns, ne]] + right

