def min_meeting_rooms(intervals):
    starts = sorted(i[0] for i in intervals)
    ends = sorted(i[1] for i in intervals)
    rooms = 0; e = 0
    for s in starts:
        if s < ends[e]:
            rooms += 1
        else:
            e += 1
    return rooms

import heapq
def min_meeting_rooms(intervals):
    intervals.sort()
    heap = []
    for s, e in intervals:
        if heap and heap[0] <= s:
            heapq.heappop(heap)
        heapq.heappush(heap, e)
    return len(heap)

def find_min_arrow_shots(points):
    points.sort(key=lambda x: x[1])
    arrows = 1; cur = points[0][1]
    for s, e in points[1:]:
        if s > cur:
            arrows += 1; cur = e
    return arrows

def find_min_arrow_shots(points):
    points.sort()
    arrows = 0; end = None
    for s, e in points:
        if end is None or s > end:
            arrows += 1; end = e
        else:
            end = min(end, e)
    return arrows
